import React, { useState, useCallback } from 'react';
import { useDropzone } from 'react-dropzone';
import { Upload, X, Check, AlertCircle, Image as ImageIcon } from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';
import { useImageUpload } from '../../hooks/useImageUpload';

const ImageUpload = ({ currentImage, onImageUploaded, onImageRemoved }) => {
    const [preview, setPreview] = useState(currentImage || null);
    const { uploadImage, uploading, progress, error } = useImageUpload();

    const onDrop = useCallback(async (acceptedFiles) => {
        const file = acceptedFiles[0];
        if (!file) return;

        // Show preview immediately
        const reader = new FileReader();
        reader.onload = () => setPreview(reader.result);
        reader.readAsDataURL(file);

        try {
            const result = await uploadImage(file);
            setPreview(result.url);
            onImageUploaded(result.url, result.path);
        } catch (err) {
            console.error('Upload error:', err);
            setPreview(currentImage);
        }
    }, [uploadImage, onImageUploaded, currentImage]);

    const { getRootProps, getInputProps, isDragActive } = useDropzone({
        onDrop,
        accept: {
            'image/*': ['.jpeg', '.jpg', '.png', '.webp']
        },
        maxFiles: 1,
        disabled: uploading
    });

    const handleRemove = () => {
        setPreview(null);
        onImageRemoved();
    };

    return (
        <div className="space-y-4">
            <label className="text-[10px] font-black text-gray-500 uppercase tracking-widest ml-1">
                Project Image
            </label>

            {preview ? (
                <div className="relative group">
                    <img
                        src={preview}
                        alt="Preview"
                        className="w-full h-64 object-cover rounded-2xl border border-white/10"
                    />
                    <div className="absolute inset-0 bg-black/60 opacity-0 group-hover:opacity-100 transition-opacity rounded-2xl flex items-center justify-center gap-4">
                        <button
                            type="button"
                            onClick={handleRemove}
                            className="p-3 bg-red-500 hover:bg-red-600 text-white rounded-full transition-all"
                        >
                            <X size={20} />
                        </button>
                        <div {...getRootProps()} className="cursor-pointer">
                            <input {...getInputProps()} />
                            <button
                                type="button"
                                className="p-3 bg-orange-500 hover:bg-orange-600 text-white rounded-full transition-all"
                            >
                                <Upload size={20} />
                            </button>
                        </div>
                    </div>
                </div>
            ) : (
                <div
                    {...getRootProps()}
                    className={`
                        relative border-2 border-dashed rounded-2xl p-12 text-center cursor-pointer transition-all
                        ${isDragActive
                            ? 'border-orange-500 bg-orange-500/10'
                            : 'border-white/20 hover:border-orange-500/50 bg-white/5 hover:bg-white/10'
                        }
                        ${uploading ? 'pointer-events-none opacity-50' : ''}
                    `}
                >
                    <input {...getInputProps()} />

                    <div className="flex flex-col items-center gap-4">
                        <div className={`p-6 rounded-full ${isDragActive ? 'bg-orange-500' : 'bg-white/10'} transition-colors`}>
                            {uploading ? (
                                <div className="w-12 h-12 border-4 border-white/20 border-t-orange-500 rounded-full animate-spin" />
                            ) : (
                                <ImageIcon size={48} className={isDragActive ? 'text-white' : 'text-gray-400'} />
                            )}
                        </div>

                        {uploading ? (
                            <div className="w-full max-w-xs">
                                <div className="flex justify-between text-sm mb-2">
                                    <span className="text-gray-400">Uploading...</span>
                                    <span className="text-orange-500 font-bold">{Math.round(progress)}%</span>
                                </div>
                                <div className="w-full h-2 bg-white/10 rounded-full overflow-hidden">
                                    <motion.div
                                        initial={{ width: 0 }}
                                        animate={{ width: `${progress}%` }}
                                        className="h-full bg-gradient-to-r from-orange-500 to-orange-600"
                                    />
                                </div>
                            </div>
                        ) : (
                            <>
                                <div>
                                    <p className="text-white font-bold mb-1">
                                        {isDragActive ? 'Drop image here' : 'Drag & drop image here'}
                                    </p>
                                    <p className="text-gray-500 text-sm">or click to browse</p>
                                </div>
                                <p className="text-xs text-gray-600">
                                    Supports: JPG, PNG, WebP (max 5MB)
                                </p>
                            </>
                        )}
                    </div>
                </div>
            )}

            <AnimatePresence>
                {error && (
                    <motion.div
                        initial={{ opacity: 0, y: -10 }}
                        animate={{ opacity: 1, y: 0 }}
                        exit={{ opacity: 0, y: -10 }}
                        className="flex items-center gap-2 p-4 bg-red-500/10 border border-red-500/20 rounded-xl text-red-500 text-sm"
                    >
                        <AlertCircle size={18} />
                        <span>{error}</span>
                    </motion.div>
                )}
            </AnimatePresence>
        </div>
    );
};

export default ImageUpload;

import React, { useState } from 'react';
import React, { useState } from 'react';
import { Maximize2, Minimize2, Type, Volume2, VolumeX } from 'lucide-react';

const AccessibilityTools = () => {
    const [fontSize, setFontSize] = useState(100);
    const [speaking, setSpeaking] = useState(false);

    const increaseFontSize = () => {
        const newSize = Math.min(fontSize + 10, 150);
        setFontSize(newSize);
        document.documentElement.style.fontSize = `${newSize}%`;
    };

    const decreaseFontSize = () => {
        const newSize = Math.max(fontSize - 10, 80);
        setFontSize(newSize);
        document.documentElement.style.fontSize = `${newSize}%`;
    };

    const resetFontSize = () => {
        setFontSize(100);
        document.documentElement.style.fontSize = '100%';
    };

    const toggleTextToSpeech = () => {
        if (speaking) {
            window.speechSynthesis.cancel();
            setSpeaking(false);
        } else {
            const text = document.querySelector('.project-description')?.textContent || '';
            const utterance = new SpeechSynthesisUtterance(text);
            window.speechSynthesis.speak(utterance);
            setSpeaking(true);

            utterance.onend = () => setSpeaking(false);
        }
    };

    return (
        <div className="flex items-center gap-2">
            {/* Font Size Controls */}
            <div className="flex items-center gap-1 px-3 py-2 bg-white/5 backdrop-blur-xl border border-white/10 rounded-xl">
                <button
                    onClick={decreaseFontSize}
                    className="p-1.5 hover:bg-white/10 rounded-lg transition-colors"
                    title="Decrease font size"
                >
                    <Minimize2 size={16} className="text-gray-400" />
                </button>
                <span className="text-xs font-bold text-gray-400 px-2">{fontSize}%</span>
                <button
                    onClick={increaseFontSize}
                    className="p-1.5 hover:bg-white/10 rounded-lg transition-colors"
                    title="Increase font size"
                >
                    <Maximize2 size={16} className="text-gray-400" />
                </button>
                <button
                    onClick={resetFontSize}
                    className="p-1.5 hover:bg-white/10 rounded-lg transition-colors ml-1"
                    title="Reset font size"
                >
                    <Type size={16} className="text-gray-400" />
                </button>
            </div>

            {/* Text to Speech */}
            <button
                onClick={toggleTextToSpeech}
                className={`p-2.5 backdrop-blur-xl border rounded-xl transition-all ${speaking
                    ? 'bg-orange-500/20 border-orange-500/30'
                    : 'bg-white/5 border-white/10 hover:bg-white/10'
                    }`}
                title={speaking ? 'Stop reading' : 'Read aloud'}
            >
                {speaking ? (
                    <VolumeX size={18} className="text-orange-400" />
                ) : (
                    <Volume2 size={18} className="text-gray-400" />
                )}
            </button>
        </div>
    );
};

export default AccessibilityTools;

import React, { useState, useRef, useEffect } from 'react';
import { GripVertical } from 'lucide-react';

const BeforeAfterSlider = ({ before, after, title = "Before vs After" }) => {
    const [sliderPosition, setSliderPosition] = useState(50);
    const [isDragging, setIsDragging] = useState(false);
    const containerRef = useRef(null);

    const handleMove = (event) => {
        if (!isDragging && event.type !== 'click') return;

        const containerRect = containerRef.current.getBoundingClientRect();
        const clientX = event.touches ? event.touches[0].clientX : event.clientX;

        const position = ((clientX - containerRect.left) / containerRect.width) * 100;
        const clampedPosition = Math.min(Math.max(position, 0), 100);

        setSliderPosition(clampedPosition);
    };

    const handleMouseDown = () => setIsDragging(true);
    const handleMouseUp = () => setIsDragging(false);

    useEffect(() => {
        document.addEventListener('mouseup', handleMouseUp);
        document.addEventListener('touchend', handleMouseUp);
        return () => {
            document.removeEventListener('mouseup', handleMouseUp);
            document.removeEventListener('touchend', handleMouseUp);
        };
    }, []);

    return (
        <div className="w-full max-w-5xl mx-auto mb-20 animate-fade-in relative z-10">
            <div className="text-center mb-10">
                <h2 className="text-3xl md:text-4xl font-black text-white mb-4">Project Transformation</h2>
                <p className="text-gray-400 max-w-2xl mx-auto">
                    Drag the slider to see the visual evolution and improvements made during the development process.
                </p>
            </div>

            <div
                ref={containerRef}
                className="relative w-full aspect-video rounded-3xl overflow-hidden cursor-ew-resize select-none border border-white/10 shadow-2xl bg-[#0A0A0A]"
                onMouseMove={handleMove}
                onTouchMove={handleMove}
                onClick={handleMove}
            >
                {/* After Image (Background) */}
                <div className="absolute inset-0">
                    <img
                        src={after}
                        alt="After transformation"
                        className="w-full h-full object-cover"
                        draggable="false"
                    />
                    <div className="absolute top-4 right-4 bg-black/60 backdrop-blur-md px-3 py-1 rounded-full text-xs font-bold text-white border border-white/10 pointer-events-none">
                        AFTER
                    </div>
                </div>

                {/* Before Image (Clipped) */}
                <div
                    className="absolute inset-0 overflow-hidden"
                    style={{ width: `${sliderPosition}%` }}
                >
                    <img
                        src={before}
                        alt="Before transformation"
                        className="w-full h-full object-cover max-w-none"
                        style={{ width: `${containerRef.current?.offsetWidth}px` }}
                        draggable="false"
                    />
                    <div className="absolute top-4 left-4 bg-black/60 backdrop-blur-md px-3 py-1 rounded-full text-xs font-bold text-white border border-white/10 pointer-events-none">
                        BEFORE
                    </div>
                </div>

                {/* Slider Handle */}
                <div
                    className="absolute top-0 bottom-0 w-1 bg-white cursor-ew-resize shadow-[0_0_20px_rgba(255,255,255,0.5)] z-20"
                    style={{ left: `${sliderPosition}%` }}
                    onMouseDown={handleMouseDown}
                    onTouchStart={handleMouseDown}
                >
                    <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-10 h-10 bg-white rounded-full flex items-center justify-center shadow-lg text-black transition-transform hover:scale-110 active:scale-95">
                        <GripVertical size={20} />
                    </div>
                </div>

                {/* Overlay Gradient for depth */}
                <div className="absolute inset-0 shadow-[inset_0_0_50px_rgba(0,0,0,0.5)] pointer-events-none rounded-3xl"></div>
            </div>
        </div>
    );
};

export default BeforeAfterSlider;

import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { Code, Copy, Check, Terminal } from 'lucide-react';

const CodeSnippetViewer = ({ snippets, title }) => {
    const [activeTab, setActiveTab] = useState(0);
    const [copied, setCopied] = useState(false);

    // Fallback snippets for demo if none provided
    const displaySnippets = snippets && snippets.length > 0 ? snippets : [
        {
            language: 'javascript',
            filename: 'example.js',
            code: `// Sample code for ${title}\nfunction initializeProject() {\n  console.log("Project Initialized");\n  return true;\n}`
        }
    ];

    const copyToClipboard = async () => {
        try {
            await navigator.clipboard.writeText(displaySnippets[activeTab].code);
            setCopied(true);
            setTimeout(() => setCopied(false), 2000);
        } catch (err) {
            console.error('Failed to copy:', err);
        }
    };

    return (
        <div className="bg-gradient-to-br from-white/5 to-white/10 backdrop-blur-xl border border-white/10 rounded-3xl overflow-hidden shadow-xl">
            {/* Header / Tabs */}
            <div className="flex items-center justify-between px-6 py-4 bg-white/5 border-b border-white/10">
                <div className="flex items-center gap-6 overflow-x-auto no-scrollbar">
                    {displaySnippets.map((snippet, index) => (
                        <button
                            key={index}
                            onClick={() => setActiveTab(index)}
                            className={`flex items-center gap-2 py-2 transition-all relative ${activeTab === index ? 'text-orange-500' : 'text-gray-400 hover:text-white'
                                }`}
                        >
                            <Terminal size={14} />
                            <span className="text-sm font-bold whitespace-nowrap">
                                {snippet.filename || snippet.language}
                            </span>
                            {activeTab === index && (
                                <motion.div
                                    layoutId="activeTab"
                                    className="absolute -bottom-4 left-0 right-0 h-[2px] bg-orange-500"
                                />
                            )}
                        </button>
                    ))}
                </div>
                <button
                    onClick={copyToClipboard}
                    className="p-2 hover:bg-white/10 rounded-lg transition-all text-gray-400 hover:text-white"
                    title="Copy Code"
                >
                    {copied ? <Check size={18} className="text-green-500" /> : <Copy size={18} />}
                </button>
            </div>

            {/* Code Content */}
            <div className="p-6 overflow-x-auto">
                <pre className="text-sm md:text-base font-mono leading-relaxed">
                    <code className="text-gray-300">
                        {displaySnippets[activeTab].code.split('\n').map((line, i) => (
                            <div key={i} className="flex gap-4 group">
                                <span className="text-gray-600 select-none text-right w-8">{i + 1}</span>
                                <span className="group-hover:text-white transition-colors">{line}</span>
                            </div>
                        ))}
                    </code>
                </pre>
            </div>

            {/* Language Badge */}
            <div className="px-6 py-3 bg-white/5 border-t border-white/10 flex justify-end">
                <div className="flex items-center gap-2">
                    <Code size={12} className="text-gray-500" />
                    <span className="text-xs font-black uppercase tracking-widest text-gray-500">
                        {displaySnippets[activeTab].language}
                    </span>
                </div>
            </div>
        </div>
    );
};

