                        <h3 className="text-2xl font-black text-white uppercase tracking-wider">
                            Project Gallery
                        </h3>
                    </div>
                    <div className="px-4 py-2 bg-purple-500/20 border border-purple-500/30 rounded-full">
                        <span className="text-sm font-bold text-purple-400">
