export default ProjectTimeline;

import React, { useEffect, useRef } from 'react';
import { motion } from 'framer-motion';
import { X, Download } from 'lucide-react';

const QRCodeGenerator = ({ url, title, onClose }) => {
    const qrRef = useRef(null);

    useEffect(() => {
        // Generate QR code using a simple API
        if (qrRef.current) {
            const qrUrl = `https://api.qrserver.com/v1/create-qr-code/?size=300x300&data=${encodeURIComponent(url)}`;
            qrRef.current.src = qrUrl;
        }
    }, [url]);

    const downloadQR = () => {
        const link = document.createElement('a');
        link.href = qrRef.current.src;
        link.download = `${title.replace(/\s+/g, '-')}-QR-Code.png`;
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
    };

    return (
        <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            onClick={onClose}
            className="fixed inset-0 bg-black/80 backdrop-blur-sm z-[100] flex items-center justify-center p-4"
        >
            <motion.div
                initial={{ scale: 0.9, y: 20 }}
                animate={{ scale: 1, y: 0 }}
                exit={{ scale: 0.9, y: 20 }}
                onClick={(e) => e.stopPropagation()}
                className="bg-[#0A0A0A] border border-white/10 rounded-3xl p-8 max-w-md w-full shadow-2xl"
            >
                {/* Header */}
                <div className="flex items-center justify-between mb-6">
                    <h3 className="text-2xl font-black text-white">QR Code</h3>
                    <button
                        onClick={onClose}
                        className="p-2 hover:bg-white/10 rounded-full transition-colors"
                    >
                        <X size={24} className="text-gray-400" />
                    </button>
                </div>

                {/* QR Code Display */}
                <div className="bg-white rounded-2xl p-6 mb-6 flex items-center justify-center">
                    <img
                        ref={qrRef}
                        alt="QR Code"
                        className="w-full max-w-[300px] h-auto"
                    />
                </div>

                {/* Project Title */}
                <p className="text-center text-gray-400 mb-6 font-medium">
                    Scan to view: <span className="text-white font-bold">{title}</span>
                </p>

                {/* Download Button */}
                <button
                    onClick={downloadQR}
                    className="w-full px-6 py-4 bg-gradient-to-r from-orange-500 to-orange-600 text-white rounded-2xl font-bold flex items-center justify-center gap-3 hover:shadow-xl hover:shadow-orange-500/30 transition-all"
                >
                    <Download size={20} />
                    <span>Download QR Code</span>
                </button>

                {/* URL Display */}
                <div className="mt-4 p-4 bg-white/5 rounded-xl border border-white/10">
                    <p className="text-xs text-gray-500 mb-1 uppercase tracking-wider">URL</p>
                    <p className="text-sm text-gray-300 break-all font-mono">{url}</p>
                </div>
            </motion.div>
        </motion.div>
    );
};

export default QRCodeGenerator;

import React from 'react';
import { motion } from 'framer-motion';
import { useNavigate } from 'react-router-dom';
import { useData } from '../../context/DataContext';
import { Sparkles, ArrowRight } from 'lucide-react';

const RelatedProjects = ({ currentProjectId, tags = [] }) => {
    const { data } = useData();
    const navigate = useNavigate();

    // Find projects with matching tags
    const related = data?.projects?.filter(p =>
        p.id !== currentProjectId &&
        (p.tags?.some(tag => tags.includes(tag)) || p.level === data?.projects?.find(cp => cp.id === currentProjectId)?.level)
    ).slice(0, 3) || [];

    if (related.length === 0) return null;

    return (
        <div className="mt-20">
            <div className="flex items-center gap-4 mb-10">
                <h3 className="text-sm font-black uppercase tracking-[0.3em] text-white">
                    Related Projects
                </h3>
                <div className="flex-1 h-[1px] bg-gradient-to-r from-white/20 to-transparent"></div>
            </div>

            <div className="grid md:grid-cols-3 gap-8">
                {related.map((project, index) => (
                    <motion.div
                        key={project.id}
                        initial={{ opacity: 0, y: 30 }}
                        whileInView={{ opacity: 1, y: 0 }}
                        viewport={{ once: true }}
                        transition={{ delay: index * 0.1 }}
                        onClick={() => navigate(`/project/${project.id}`)}
                        className="group cursor-pointer"
                    >
                        <div className="relative aspect-video rounded-3xl overflow-hidden border border-white/10 mb-6 transition-all duration-500 group-hover:border-orange-500/50 group-hover:scale-[1.02] shadow-2xl">
                            <img
                                src={project.image}
                                alt={project.title}
                                className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700"
                            />
                            <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-transparent to-transparent opacity-0 group-hover:opacity-100 transition-opacity"></div>

                            {/* View Button Overlay */}
                            <div className="absolute inset-0 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity">
                                <div className="px-6 py-2 bg-white text-black rounded-full font-bold flex items-center gap-2">
                                    <span>View Project</span>
                                    <ArrowRight size={16} />
                                </div>
                            </div>
                        </div>

                        <div className="px-2">
                            <div className="flex items-center gap-2 mb-2">
                                <Sparkles size={12} className="text-orange-500" />
                                <span className="text-[10px] font-black uppercase tracking-widest text-orange-500/80">
                                    {project.level} Project
                                </span>
                            </div>
                            <h4 className="text-xl font-black text-white group-hover:text-orange-500 transition-colors mb-2 line-clamp-1">
                                {project.title}
                            </h4>
                            <p className="text-sm text-gray-400 line-clamp-2 leading-relaxed">
                                {project.description}
                            </p>
                        </div>
                    </motion.div>
                ))}
            </div>
        </div>
    );
};

export default RelatedProjects;

