import React, { useState, useEffect, useRef } from 'react';
import { motion } from 'framer-motion';

const LazyImage = ({ 
    src, 
    alt, 
    className = '', 
    placeholderSrc = 'data:image/svg+xml,%3Csvg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 300"%3E%3Crect fill="%23111" width="400" height="300"/%3E%3C/svg%3E',
    ...props 
}) => {
    const [imageSrc, setImageSrc] = useState(placeholderSrc);
    const [imageLoaded, setImageLoaded] = useState(false);
    const [isInView, setIsInView] = useState(false);
    const imgRef = useRef(null);

    useEffect(() => {
        const observer = new IntersectionObserver(
            (entries) => {
                entries.forEach((entry) => {
                    if (entry.isIntersecting) {
                        setIsInView(true);
                        observer.disconnect();
                    }
                });
            },
            {
                rootMargin: '50px', // Start loading 50px before image enters viewport
            }
        );

        if (imgRef.current) {
            observer.observe(imgRef.current);
        }

        return () => {
            if (imgRef.current) {
                observer.unobserve(imgRef.current);
            }
        };
    }, []);

    useEffect(() => {
        if (isInView && src) {
            const img = new Image();
            img.src = src;
            img.onload = () => {
                setImageSrc(src);
                setImageLoaded(true);
            };
        }
    }, [isInView, src]);

    return (
        <div ref={imgRef} className="relative overflow-hidden">
            <motion.img
                src={imageSrc}
                alt={alt}
                className={`${className} ${!imageLoaded ? 'blur-sm scale-105' : ''} transition-all duration-700`}
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                {...props}
            />
            {!imageLoaded && (
                <div className="absolute inset-0 bg-gradient-to-br from-white/5 to-white/0 animate-pulse" />
            )}
        </div>
    );
};

export default LazyImage;

import React, { useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { ChevronLeft, ChevronRight } from 'lucide-react';
import { motion } from 'framer-motion';
import { useData } from '../../context/DataContext';

const ProjectNavigation = ({ currentProjectId }) => {
    const navigate = useNavigate();
    const { data } = useData();
    const projects = data?.projects || [];

    const currentIndex = projects.findIndex(p => p.id === currentProjectId);
    const prevProject = currentIndex > 0 ? projects[currentIndex - 1] : projects[projects.length - 1];
    const nextProject = currentIndex < projects.length - 1 ? projects[currentIndex + 1] : projects[0];

    // Keyboard navigation
    useEffect(() => {
        const handleKeyPress = (e) => {
            if (e.key === 'ArrowLeft' && prevProject) {
                navigate(`/project/${prevProject.id}`);
            } else if (e.key === 'ArrowRight' && nextProject) {
                navigate(`/project/${nextProject.id}`);
            }
        };

        window.addEventListener('keydown', handleKeyPress);
        return () => window.removeEventListener('keydown', handleKeyPress);
    }, [prevProject, nextProject, navigate]);

    if (projects.length <= 1) return null;

    return (
        <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.8 }}
            className="flex items-center justify-between gap-4 py-12 border-t border-white/10"
        >
            {/* Previous Project */}
            <button
                onClick={() => navigate(`/project/${prevProject.id}`)}
                className="group flex items-center gap-4 flex-1 p-6 bg-white/5 hover:bg-white/10 rounded-2xl border border-white/10 hover:border-orange-500/30 transition-all text-left"
            >
                <div className="flex items-center justify-center w-12 h-12 bg-white/10 rounded-full group-hover:bg-orange-500 transition-all">
                    <ChevronLeft size={24} className="group-hover:-translate-x-1 transition-transform" />
                </div>
                <div className="flex-1 min-w-0">
                    <p className="text-xs font-black uppercase tracking-widest text-gray-500 mb-1">Previous</p>
                    <h3 className="text-white font-bold truncate group-hover:text-orange-500 transition-colors">
                        {prevProject.title}
                    </h3>
                </div>
            </button>

            {/* Next Project */}
            <button
                onClick={() => navigate(`/project/${nextProject.id}`)}
                className="group flex items-center gap-4 flex-1 p-6 bg-white/5 hover:bg-white/10 rounded-2xl border border-white/10 hover:border-orange-500/30 transition-all text-right"
            >
                <div className="flex-1 min-w-0">
                    <p className="text-xs font-black uppercase tracking-widest text-gray-500 mb-1">Next</p>
                    <h3 className="text-white font-bold truncate group-hover:text-orange-500 transition-colors">
                        {nextProject.title}
                    </h3>
                </div>
                <div className="flex items-center justify-center w-12 h-12 bg-white/10 rounded-full group-hover:bg-orange-500 transition-all">
                    <ChevronRight size={24} className="group-hover:translate-x-1 transition-transform" />
                </div>
            </button>
        </motion.div>
    );
};

export default ProjectNavigation;

import React, { useState, useEffect } from 'react';
import { Search, X } from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';

const SearchBar = ({ onSearch, placeholder = "Search projects..." }) => {
    const [searchTerm, setSearchTerm] = useState('');
    const [debouncedTerm, setDebouncedTerm] = useState('');

    // Debounce search input
    useEffect(() => {
        const timer = setTimeout(() => {
            setDebouncedTerm(searchTerm);
        }, 300);

        return () => clearTimeout(timer);
    }, [searchTerm]);

    // Call onSearch when debounced term changes
    useEffect(() => {
        onSearch(debouncedTerm);
    }, [debouncedTerm, onSearch]);

    const handleClear = () => {
        setSearchTerm('');
        setDebouncedTerm('');
    };

    return (
        <div className="relative w-full max-w-md">
            <div className="relative">
                <Search
                    size={20}
                    className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-500 pointer-events-none"
                />
                <input
                    type="text"
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                    placeholder={placeholder}
                    className="w-full bg-white/5 border border-white/10 rounded-2xl py-3 pl-12 pr-12 text-white placeholder-gray-500 focus:outline-none focus:ring-2 focus:ring-orange-500/20 focus:border-orange-500 transition-all font-medium"
                />
                <AnimatePresence>
                    {searchTerm && (
                        <motion.button
                            initial={{ opacity: 0, scale: 0.8 }}
                            animate={{ opacity: 1, scale: 1 }}
                            exit={{ opacity: 0, scale: 0.8 }}
                            onClick={handleClear}
                            className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-500 hover:text-white transition-colors"
                            aria-label="Clear search"
                        >
                            <X size={18} />
                        </motion.button>
                    )}
                </AnimatePresence>
            </div>
        </div>
    );
};

export default SearchBar;

import React, { useState } from 'react';
import { Share2, Twitter, Linkedin, Facebook, Link as LinkIcon, Check } from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';

const ShareButton = ({ url, title, description }) => {
    const [isOpen, setIsOpen] = useState(false);
    const [copied, setCopied] = useState(false);

    const shareUrl = url || window.location.href;
    const shareTitle = title || document.title;
    const shareText = description || '';

    const handleCopyLink = async () => {
        try {
            await navigator.clipboard.writeText(shareUrl);
            setCopied(true);
            setTimeout(() => setCopied(false), 2000);
        } catch (err) {
            console.error('Failed to copy:', err);
        }
    };

    const handleNativeShare = async () => {
        if (navigator.share) {
            try {
                await navigator.share({
                    title: shareTitle,
                    text: shareText,
                    url: shareUrl,
                });
            } catch (err) {
                if (err.name !== 'AbortError') {
                    console.error('Error sharing:', err);
                }
            }
        }
    };

    const shareLinks = [
        {
            name: 'Twitter',
            icon: Twitter,
            url: `https://twitter.com/intent/tweet?url=${encodeURIComponent(shareUrl)}&text=${encodeURIComponent(shareTitle)}`,
            color: 'hover:bg-blue-500'
        },
        {
            name: 'LinkedIn',
            icon: Linkedin,
            url: `https://www.linkedin.com/sharing/share-offsite/?url=${encodeURIComponent(shareUrl)}`,
            color: 'hover:bg-blue-600'
        },
        {
            name: 'Facebook',
            icon: Facebook,
            url: `https://www.facebook.com/sharer/sharer.php?u=${encodeURIComponent(shareUrl)}`,
            color: 'hover:bg-blue-700'
        }
    ];

    return (
        <div className="relative">
            <button
                onClick={() => setIsOpen(!isOpen)}
                className="flex items-center gap-2 px-6 py-3 bg-white/5 backdrop-blur-xl hover:bg-white/10 text-white rounded-xl transition-all border border-white/10 font-bold group"
                aria-label="Share project"
            >
                <Share2 size={18} className="group-hover:rotate-12 transition-transform" />
                <span className="hidden sm:inline">Share</span>
            </button>

            <AnimatePresence>
                {isOpen && (
                    <>
                        {/* Backdrop */}
                        <div
                            className="fixed inset-0 z-40"
                            onClick={() => setIsOpen(false)}
                        />

                        {/* Dropdown Menu */}
                        <motion.div
                            initial={{ opacity: 0, y: -10, scale: 0.95 }}
                            animate={{ opacity: 1, y: 0, scale: 1 }}
                            exit={{ opacity: 0, y: -10, scale: 0.95 }}
                            transition={{ duration: 0.2 }}
                            className="absolute right-0 mt-2 w-56 bg-[#0F0F0F] backdrop-blur-xl border border-white/10 rounded-2xl shadow-2xl overflow-hidden z-50"
                        >
                            <div className="p-2">
                                {/* Native Share (Mobile) */}
                                {navigator.share && (
                                    <button
                                        onClick={handleNativeShare}
                                        className="w-full flex items-center gap-3 px-4 py-3 text-white hover:bg-white/10 rounded-xl transition-all text-left"
                                    >
                                        <Share2 size={18} />
                                        <span className="font-medium">Share via...</span>
                                    </button>
                                )}

                                {/* Social Media Links */}
                                {shareLinks.map((platform) => (
                                    <a
                                        key={platform.name}
                                        href={platform.url}
                                        target="_blank"
                                        rel="noopener noreferrer"
                                        className={`w-full flex items-center gap-3 px-4 py-3 text-white ${platform.color} rounded-xl transition-all`}
                                        onClick={() => setIsOpen(false)}
                                    >
                                        <platform.icon size={18} />
                                        <span className="font-medium">{platform.name}</span>
                                    </a>
                                ))}

                                {/* Copy Link */}
                                <button
                                    onClick={handleCopyLink}
                                    className="w-full flex items-center gap-3 px-4 py-3 text-white hover:bg-orange-500/20 rounded-xl transition-all text-left"
                                >
                                    {copied ? (
                                        <>
                                            <Check size={18} className="text-green-500" />
                                            <span className="font-medium text-green-500">Copied!</span>
                                        </>
                                    ) : (
                                        <>
                                            <LinkIcon size={18} />
                                            <span className="font-medium">Copy Link</span>
                                        </>
                                    )}
                                </button>
                            </div>
                        </motion.div>
                    </>
                )}
            </AnimatePresence>
        </div>
    );
};

export default ShareButton;

import React from 'react';
import { Sun, Moon } from 'lucide-react';
import { motion } from 'framer-motion';
import { useTheme } from '../../context/ThemeContext';

const ThemeToggle = () => {
    const { theme, toggleTheme } = useTheme();

    return (
        <button
            onClick={toggleTheme}
            className="relative p-3 bg-white/5 hover:bg-white/10 backdrop-blur-xl rounded-full border border-white/10 transition-all group"
            aria-label="Toggle theme"
            title={`Switch to ${theme === 'dark' ? 'light' : 'dark'} mode`}
        >
            <motion.div
                initial={false}
                animate={{ rotate: theme === 'dark' ? 0 : 180 }}
                transition={{ duration: 0.3 }}
            >
                {theme === 'dark' ? (
                    <Sun size={20} className="text-orange-500" />
                ) : (
                    <Moon size={20} className="text-blue-500" />
                )}
            </motion.div>
        </button>
    );
};

export default ThemeToggle;

import React, { createContext, useContext, useState, useEffect } from 'react';

const ThemeContext = createContext();

export const useTheme = () => {
    const context = useContext(ThemeContext);
    if (!context) {
        throw new Error('useTheme must be used within ThemeProvider');
    }
    return context;
};

export const ThemeProvider = ({ children }) => {
    const [theme, setTheme] = useState(() => {
        // Check localStorage first
        const savedTheme = localStorage.getItem('theme');
        if (savedTheme) return savedTheme;

        // Check system preference
        if (window.matchMedia('(prefers-color-scheme: dark)').matches) {
            return 'dark';
        }

        return 'dark'; // Default to dark
    });

    useEffect(() => {
        const root = window.document.documentElement;

        if (theme === 'dark') {
            root.classList.add('dark');
        } else {
            root.classList.remove('dark');
        }

        localStorage.setItem('theme', theme);
    }, [theme]);

    const toggleTheme = () => {
        setTheme(prev => prev === 'dark' ? 'light' : 'dark');
    };

    return (
        <ThemeContext.Provider value={{ theme, toggleTheme }}>
            {children}
        </ThemeContext.Provider>
    );
};
